arguments.command:
curl -sS -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel,mpim&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'):
    print('ERROR:', d); sys.exit(1)
for t in ('channels','groups','mpims'):
    for c in d.get(t,[]):
        print(t, c['id'], c.get('name'), 'archived=' + str(c.get('is_archived')))
"

